fn longest(strings: Vec<Vec<char>>) -> Option<Vec<char>> {
    if strings.is_empty() {
        return None;
    }

    let mut max_length = 0;
    let mut longest_sequence: Option<Vec<char>> = None;

    for sequence in strings.iter() {
        let current_length = sequence.len();
        if current_length > max_length {
            max_length = current_length;
            longest_sequence = Some(sequence.clone()); // Clone the longest sequence found
        }
    }

    longest_sequence
}